/**
 * Compose→terraform bridge for `recordCreateDisplayBlocks` (CREATE surface).
 * `serializeDisplayBlocks` (`display-blocks.ts`) turns the authored
 * `DisplayBlock[]` into the GraphQL-compose wire shape consumed by `to-tf`
 * payloads — this module maps THAT wire shape into
 * `RecordCreateFormSectionWire[]`, the shape `recordCreateFormToTf`
 * (`entities/record-create-form/to-tf.ts`) already knows how to emit as
 * `elementum_record_create_form`.
 *
 * Only `field`/`group` blocks have a `elementum_record_create_form`
 * equivalent — the provider's `sections` schema has no `widget`/`comments`
 * section type, same restriction `display-blocks-to-layout.ts` documents for
 * the LAYOUT surface. `widget`/`comments` blocks are diagnosed and dropped
 * individually rather than killing the whole payload. Record-create-form
 * sections are flat (`fields` only) — a `group` nested inside a `group` is
 * diagnosed and dropped (its own contents only; the outer group keeps its
 * direct fields), since there is no nested-section shape to target.
 *
 * Unlike `AppLayoutSectionWire`, `RecordCreateFormSectionWire` carries no
 * section-type discriminator at all (no `type: "group"` to set) — otherwise
 * the mapping is identical, so this is intentionally a near-duplicate of
 * `displayBlocksToLayoutSections` rather than a shared generic: the two
 * target wire shapes are close enough to invite one, but diverge exactly at
 * the field this module must NOT set.
 *
 * This is a pure, entity-agnostic transform (it knows nothing about apps or
 * elements) — kept alongside `display-blocks.ts` rather than under
 * `entities/element/`.
 */
import type { RecordCreateFormSectionWire } from "../record-create-form/to-tf.js";
/**
 * Maps serialized `recordCreateDisplayBlocks` (the `Record<string,
 * unknown>[]` shape `serializeDisplayBlocks` produces) into
 * `elementum_record_create_form` sections.
 *
 * - A top-level `GROUP` block → one section (`name`/`icon`/`color`/
 *   `maxColumns` carried over, `fields` from its direct `FIELD` children).
 *   `displayOrder`/`displayLocation`/`sideNavItem`/`hidden`/`agent` are not
 *   authorable through `DisplayBlock` — `recordCreateFormToTf` defaults them
 *   (index-based `display_order`, `"CENTER"`, `true`, `false`) the same way
 *   it does for a directly-authored `recordCreateForm` section that omits
 *   them.
 * - Top-level `FIELD` blocks with no enclosing group are collected into one
 *   implicit group section named `"Details"` (the target shape requires a
 *   non-empty section name — see `IMPLICIT_GROUP_NAME`). Intentionally
 *   always appended LAST, after every named `GROUP` section — see
 *   `displayBlocksToLayoutSections`'s doc comment for why a fixed,
 *   deterministic position was chosen over inferring one from interleaving.
 * - `WIDGET`/`COMMENTS` blocks (top-level or nested) and nested `GROUP`
 *   blocks are diagnosed and dropped individually; everything else mappable
 *   in the same payload still lands. A block with no recognizable shape at
 *   all (not a record, or missing/malformed `properties.type`) is likewise
 *   diagnosed and dropped rather than silently ignored.
 */
export declare function displayBlocksToRecordCreateFormSections(blocks: readonly unknown[], where: string, diagnostics: string[]): RecordCreateFormSectionWire[];
